import { useRef, useState } from "react";
import { Badge, Banner, Button, Image } from "@kit/index.js";
import { LocalizedText, TrackingScope, Translate, useExperimentTracking, useImpression, useLocalized, useTrack, useTranslation } from "travel-platform";
import "./catalog.js";
import styles from "./MerchBanner.module.css";

export default function MerchBanner({ banner }) {
    const t = useTranslation();
    const localized = useLocalized();
    const track = useTrack();
    const ref = useRef(null);
    const [dismissed, setDismissed] = useState(false);
    useImpression(ref, `banner:${banner.id}`, { bannerId: banner.id, kind: banner.kind });
    useExperimentTracking(banner.tracking);
    if (dismissed)
        return null;
    return (
        <TrackingScope surface={`banner-${banner.kind.toLowerCase()}`}>
            <div ref={ref} className={styles.wrapper} data-testid="merch-banner">
                <Banner
                    variant={banner.kind === "DEALS" ? "brand" : "neutral"}
                    title={localized(banner.title)}
                    image={banner.image ? <Image src={banner.image.url} width={banner.image.width} height={banner.image.height} alt="" ratio="4 / 3" /> : null}
                    action={banner.action ? <Button variant="primary" size="medium" href={banner.action.link.href} onClick={() => track("banner.click", { id: banner.id })}><LocalizedText value={banner.action.label} /></Button> : null}
                    onClose={() => setDismissed(true)}
                    closeLabel={t("mb.dismiss")}
                >
                    {banner.kind === "DEALS" ? <Badge variant="constructive" emphasis="strong" className={styles.badge}><Translate id="mb.sponsored" /></Badge> : null}
                    <LocalizedText value={banner.body} />
                </Banner>
            </div>
        </TrackingScope>
    );
}
